  # When a kanji is requested, init the map entry the first time. Always return the required Kanji object
  def kanji(key)
    begin
      @kanji_map[key] ||= Kanji.new(*@kanji_data[key.to_sym()])
    rescue
      $stderr.puts("FastKanji: UNKNOWN kanji for [#{key}]")
      return nil
    end
  end
